// One item per monitored workflow: its silent-failure status plus context for the AI.
const cfg = $('Configure settings').first().json;
const now = Date.now();
const HOUR = 3600000;
let overrides = {};
try { overrides = JSON.parse(cfg.max_silence_overrides || '{}'); } catch (e) { overrides = {}; }

function scheduleHours(nodes) {
  const trig = (nodes || []).find(n => n.type === 'n8n-nodes-base.scheduleTrigger' && !n.disabled);
  if (!trig) return null;
  let min = Infinity;
  for (const i of ((trig.parameters || {}).rule || {}).interval || [{}]) {
    const f = i.field || 'days';
    const h = { seconds: (i.secondsInterval || 30) / 3600, minutes: (i.minutesInterval || 5) / 60,
                hours: i.hoursInterval || 1, days: (i.daysInterval || 1) * 24,
                weeks: (i.weeksInterval || 1) * 168, months: (i.monthsInterval || 1) * 744 }[f];
    if (h) min = Math.min(min, h);       // cron expressions are skipped
  }
  return min === Infinity ? null : min;
}

function outputCount(ex) {
  const rd = ex.data && ex.data.resultData;
  const runs = rd && rd.runData && rd.lastNodeExecuted && rd.runData[rd.lastNodeExecuted];
  if (!runs || !runs.length) return null;
  return ((runs[runs.length - 1].data || {}).main || []).reduce((s, o) => s + (o ? o.length : 0), 0);
}

const byWf = {};
for (const { json: e } of $input.all()) if (e && e.workflowId) (byWf[e.workflowId] ||= []).push(e);

return $('Skip excluded workflows').all().map(({ json: w }) => {
  const ok = (byWf[w.id] || [])
    .filter(r => r.status === 'success' || (r.finished && !r.status))
    .sort((a, b) => new Date(b.startedAt) - new Date(a.startedAt));
  const counts = ok.map(outputCount).filter(c => c !== null);
  const lastOk = ok[0] ? new Date(ok[0].stoppedAt || ok[0].startedAt).getTime() : null;
  const problems = [];

  // Missed schedule
  const period = scheduleHours(w.nodes);
  const override = overrides[w.name];
  const maxSilence = override ?? (period ? period * cfg.schedule_grace_multiplier + 0.25 : null);
  const silentFor = lastOk ? (now - lastOk) / HOUR : null;
  const activeFor = w.updatedAt ? (now - new Date(w.updatedAt).getTime()) / HOUR : Infinity;
  if (maxSilence && ((silentFor === null && activeFor > maxSilence) || silentFor > maxSilence)) {
    problems.push(['missed_schedule', `No successful run for ${silentFor === null ? 'over ' + Math.round(maxSilence) : Math.round(silentFor)}h (${override ? 'allowed ' + override + 'h' : 'scheduled every ' + Math.round(period * 10) / 10 + 'h'})`]);
  }

  // Zero output
  const n = cfg.zero_output_runs;
  if (counts.length >= n && counts.slice(0, n).every(c => c === 0)) {
    problems.push(['zero_output', `Last ${n} successful runs produced 0 items`]);
  } else if (counts.length >= 4) {
    // Volume drop vs median of earlier runs
    const prior = counts.slice(1).sort((a, b) => a - b);
    const median = prior[Math.floor(prior.length / 2)];
    if (median >= 5 && counts[0] < median * cfg.volume_drop_percent / 100) {
      problems.push(['volume_drop', `Latest run produced ${counts[0]} items vs a usual ${median}`]);
    }
  }

  const trigger = (w.nodes || []).find(x => /trigger|webhook/i.test(x.type));
  return { json: {
    workflow_id: w.id,
    workflow_name: w.name,
    problem_type: problems.map(p => p[0]).join('+'),
    details: problems.map(p => p[1]).join('; '),
    trigger_type: trigger ? trigger.type.replace(/^.*\./, '') : 'unknown',
    node_types: [...new Set((w.nodes || []).map(x => x.type.replace(/^.*\./, '')))].filter(t => t !== 'stickyNote').join(', '),
    item_history: counts.join(', ') || 'no successful runs found',
  } };
});

// Raise each problem once and close it once, using the sheet as memory.
const cfg = $('Configure settings').first().json;
const open = {};
for (const { json: r } of $input.all()) if (r.status === 'open' && r.workflow_id) open[String(r.workflow_id)] = r;

const nowIso = new Date().toISOString();
const out = [];
const seen = new Set();

for (const { json: h } of $('Score workflow health').all()) {
  const id = String(h.workflow_id);
  seen.add(id);
  const prev = open[id];
  if (h.problem_type && !prev) {
    out.push({ json: { change: 'new', incident_id: `${id}-${Date.now()}`, opened_at: nowIso, ...h } });
  } else if (h.problem_type && prev && prev.problem_type !== h.problem_type) {
    out.push({ json: { change: 'resolved', ...prev, resolved_at: nowIso, note: 'replaced by a new problem type' } });
    out.push({ json: { change: 'new', incident_id: `${id}-${Date.now()}`, opened_at: nowIso, ...h } });
  } else if (!h.problem_type && prev) {
    out.push({ json: { change: 'resolved', ...prev, resolved_at: nowIso, note: 'workflow is healthy again' } });
  }
}
// Open incidents for workflows that were deactivated or excluded
for (const [id, prev] of Object.entries(open)) {
  if (!seen.has(id)) out.push({ json: { change: 'resolved', ...prev, resolved_at: nowIso, note: 'workflow deactivated or excluded' } });
}

return out.map(i => {
  i.json.slack_channel = cfg.slack_channel;
  i.json.link = `${String(cfg.n8n_base_url).replace(/\/$/, '')}/workflow/${i.json.workflow_id}/executions`;
  if (i.json.change === 'resolved') {
    i.json.downtime_hours = Math.round((Date.parse(i.json.resolved_at) - Date.parse(i.json.opened_at)) / 360000) / 10;
  }
  return i;
});

