return $input.all().map((item, i) => {
  const inc = $('Route by change').itemMatching(i).json;
  const ai = item.json.output || {};
  const sev = ai.severity === 'critical' ? 'critical' : 'warning';
  const causes = (ai.likely_causes || []).map(c => `• ${c}`).join('\n');
  return { json: {
    ...inc,
    severity: sev,
    likely_causes: (ai.likely_causes || []).join(' | '),
    check_first: ai.check_first || '',
    status: 'open',
    slack_text: `${sev === 'critical' ? ':rotating_light:' : ':warning:'} *Silent failure: ${inc.workflow_name}* (${sev})\n` +
      `${inc.details}\n*Impact:* ${ai.business_impact || 'unknown'}\n*Likely causes:*\n${causes}\n` +
      `*Check first:* ${ai.check_first || '-'}\n<${inc.link}|Open executions>`,
  } };
});
